export const genderLabel = gender => ({boy:'Chłopiec',girl:'Dziewczynka',unspecified:'Nieoznaczono'}[gender] || 'Nieoznaczono');
export function avatar(gender='unspecified',className='') {
  const color={boy:'#66b7ed',girl:'#f18bb3',unspecified:'#75c8b1'}[gender]||'#75c8b1';
  return `<svg class="baby-avatar ${className}" viewBox="0 0 96 96" role="img" aria-label="${genderLabel(gender)}"><circle cx="48" cy="48" r="47" fill="${color}" opacity=".14"/><path d="M18 83c1-19 13-30 30-30s29 11 30 30c-17 12-43 12-60 0" fill="${color}"/><path d="M36 64q12 17 24 0" fill="white" opacity=".8"/><circle cx="24" cy="42" r="7" fill="#f6c8a3"/><circle cx="72" cy="42" r="7" fill="#f6c8a3"/><ellipse cx="48" cy="39" rx="26" ry="28" fill="#ffdbb5"/><path d="M46 14c-7-7 5-11 9-4s-3 12-8 9" fill="none" stroke="#a57351" stroke-width="3" stroke-linecap="round"/><path d="M33 39q3-4 6 0m18 0q3-4 6 0" fill="none" stroke="#725849" stroke-width="2.8" stroke-linecap="round"/><ellipse cx="32" cy="48" rx="5" ry="3" fill="#f9b4a5"/><ellipse cx="64" cy="48" rx="5" ry="3" fill="#f9b4a5"/><path d="M42 49q6 9 12 0" fill="none" stroke="#bc7f66" stroke-width="2.5" stroke-linecap="round"/>${gender==='girl'?'<path d="m65 16-9-7-1 15 10-3 10 4V10Z" fill="#ec80aa"/><circle cx="65" cy="18" r="4" fill="#f5a4c3"/>':gender==='boy'?'<path d="m48 73-8-4v11l8-3 8 3V69Z" fill="#368bc5"/>':'<path d="m48 70 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z" fill="#fff"/>'}</svg>`;
}
